'use client'

/**
 * The Characters page: a viewer. A strip of characters at the top, the
 * selected character's profile, and two tabs: Generated (everything made with
 * it, in the Artifacts gallery) and References (its files, edited live).
 * Creating and editing happen in the wizard.
 *
 * URL state: `?id=` the selected character (the first one when missing),
 * `?tab=references` (Generated by default), `?new=1` the creation wizard,
 * `?edit=1` the wizard in edit mode for the selected character.
 */
import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react'
import { usePathname, useRouter, useSearchParams } from 'next/navigation'
import { toast } from 'sonner'
import { Plus, Users } from 'lucide-react'
import { AlertPanel } from '@/components/alert-panel'
import { CREDITS_PANEL_CLEARANCE } from '@/components/credits-panel'
import { EmptyState } from '@/components/empty-state'
import { MasonryGrid } from '@/components/artifacts/masonry-grid'
import { PageHeader } from '@/components/page-header'
import { Button } from '@/components/ui/button'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { useCharacterRuns } from '@/lib/characters/use-character-runs'
import { useCharacters } from '@/lib/characters/use-characters'
import type { Character, CharacterMediaKind } from '@/lib/characters/types'
import { CharacterGenerated, GALLERY_SKELETON } from './character-generated'
import { CharacterMediaSection } from './character-media-section'
import { CharacterProfile, CharacterProfileSkeleton } from './character-profile'
import { CharacterStrip, CharacterStripSkeleton } from './character-strip'
import { CharacterWizard } from './character-wizard'
import { useLiveMediaSource, type CharacterMediaActions } from './media-source'
import { cn } from '@/lib/utils'

type Tab = 'generated' | 'references'
type Changes = Record<string, string | null>

function message(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

/** Page frame: the standard content width and header. */
export function CharactersFrame({ children }: { children: ReactNode }) {
  return (
    <main className={cn("mx-auto max-w-6xl space-y-6 px-4 pb-6", CREDITS_PANEL_CLEARANCE)}>
      <PageHeader title="Characters" />
      {children}
    </main>
  )
}

export function CharactersPageSkeleton() {
  return (
    <CharactersFrame>
      <CharacterStripSkeleton />
      <CharacterProfileSkeleton />
      <MasonryGrid items={GALLERY_SKELETON} label="Loading generated media" />
    </CharactersFrame>
  )
}

export function CharactersPageBody() {
  const router = useRouter()
  const pathname = usePathname()
  const params = useSearchParams()
  const selectedId = params.get('id')
  const tab: Tab = params.get('tab') === 'references' ? 'references' : 'generated'
  const creating = params.get('new') === '1'
  const editRequested = params.get('edit') === '1'
  const state = useCharacters()
  const { characters, error, isLoading, retry, remove } = state
  // Ids this page just deleted, so their missing `?id` is not reported.
  const deleted = useRef(new Set<string>())
  // A character the wizard created with some files missing: the wizard stays
  // open on it in edit mode, even before the list holds it.
  const [handoffId, setHandoffId] = useState<string | null>(null)

  const href = useCallback((changes: Changes) => {
    const next = new URLSearchParams(params.toString())
    for (const [k, v] of Object.entries(changes)) {
      if (v == null || v === '') next.delete(k)
      else next.set(k, v)
    }
    const qs = next.toString()
    return qs ? `${pathname}?${qs}` : pathname
  }, [params, pathname])
  const replace = useCallback((changes: Changes) => router.replace(href(changes), { scroll: false }), [router, href])
  const push = (changes: Changes) => router.push(href(changes), { scroll: false })

  const selected = selectedId ? characters?.find((c) => c.id === selectedId) : undefined
  const first = characters?.[0]

  // Default selection, and a selection that no longer exists.
  useEffect(() => {
    if (!characters || selected || (selectedId && selectedId === handoffId)) return
    if (selectedId && !deleted.current.has(selectedId)) toast('That character no longer exists')
    if (first) replace({ id: first.id })
    else if (selectedId) replace({ id: null, edit: null })
  }, [characters, selected, selectedId, handoffId, first, replace])

  const runs = useCharacterRuns(selected?.id ?? null)

  const deleteSelected = async () => {
    if (!selected || !characters) return
    const { id, name } = selected
    deleted.current.add(id)
    const index = characters.findIndex((c) => c.id === id)
    const rest = characters.filter((c) => c.id !== id)
    const next = rest[Math.min(index, rest.length - 1)]
    try {
      await remove(id)
      replace({ id: next?.id ?? null, edit: null })
      toast.success(`Deleted ${name}`)
    } catch (err) {
      deleted.current.delete(id)
      toast.error(`Could not delete ${name}: ${message(err)}`)
    }
  }

  const openNew = () => replace({ new: '1', edit: null })
  const handingOff = editRequested && !!selectedId && selectedId === handoffId
  const wizardMode = creating ? 'create' : editRequested && (selected || handingOff) ? 'edit' : null

  // One key for create and edit: a partial create hands over to edit mode in the same wizard.
  const wizard = wizardMode && (
    <CharacterWizard
      key="character-wizard"
      mode={wizardMode}
      character={wizardMode === 'edit' ? selected : undefined}
      state={state}
      onClose={() => { setHandoffId(null); replace({ new: null, edit: null }) }}
      onCreated={(id) => { setHandoffId(null); replace({ id, new: null, edit: null, tab: null }) }}
      onPartial={(id) => { setHandoffId(id); replace({ id, new: null, edit: '1', tab: null }) }}
    />
  )

  let content: ReactNode
  if (isLoading) {
    return <CharactersPageSkeleton />
  } else if (error && !characters) {
    content = (
      <div className="mx-auto max-w-md space-y-3 py-8">
        <AlertPanel variant="error" title="Could not load characters">{error.message}</AlertPanel>
        <div className="flex justify-center">
          <Button type="button" variant="outline" size="sm" onClick={retry}>Retry</Button>
        </div>
      </div>
    )
  } else if (!characters || characters.length === 0) {
    content = (
      <EmptyState
        icon={Users}
        title="Create your first character"
        description="Keep a face, audio and reference clips together for your flows."
        action={(
          <Button type="button" size="lg" onClick={openNew} className="h-12 px-8 text-base has-[>svg]:px-7">
            <Plus aria-hidden className="size-5" />
            Add character
          </Button>
        )}
        className="py-24"
      />
    )
  } else {
    content = (
      <>
        <CharacterStrip
          characters={characters}
          selectedId={selected?.id ?? null}
          onSelect={(id) => { if (id !== selected?.id) push({ id, edit: null }) }}
          onNew={openNew}
        />
        {selected ? (
          <CharacterView
            key={selected.id}
            character={selected}
            actions={state}
            runs={runs}
            tab={tab}
            onTab={(t) => replace({ tab: t === 'generated' ? null : t })}
            onEdit={() => replace({ edit: '1', new: null })}
            onDelete={deleteSelected}
          />
        ) : (
          <CharacterProfileSkeleton />
        )}
      </>
    )
  }

  return (
    <CharactersFrame>
      {content}
      {wizard}
    </CharactersFrame>
  )
}

const REFERENCE_KINDS: readonly CharacterMediaKind[] = ['image', 'video', 'audio']

function CharacterView({ character, actions, runs, tab, onTab, onEdit, onDelete }: {
  character: Character
  actions: CharacterMediaActions
  runs: ReturnType<typeof useCharacterRuns>
  tab: Tab
  onTab: (tab: Tab) => void
  onEdit: () => void
  onDelete: () => Promise<void>
}) {
  const source = useLiveMediaSource(character, actions)
  const generatedCount = runs.isLoading || runs.error ? null : runs.total
  return (
    <div className="space-y-6">
      <CharacterProfile character={character} actions={actions} generated={generatedCount ?? 0} onEdit={onEdit} onDelete={onDelete} />
      <Tabs value={tab} onValueChange={(v) => onTab(v === 'references' ? 'references' : 'generated')} className="gap-4">
        <TabsList>
          <TabsTrigger value="generated" className="px-3">
            Generated
            {generatedCount !== null && <span className="text-muted-foreground tabular-nums">{generatedCount}</span>}
          </TabsTrigger>
          <TabsTrigger value="references" className="px-3">
            References
            <span className="text-muted-foreground tabular-nums">{character.media.length}</span>
          </TabsTrigger>
        </TabsList>
        <TabsContent value="generated">
          <CharacterGenerated character={character} runs={runs} />
        </TabsContent>
        <TabsContent value="references" className="grid gap-8 lg:grid-cols-[minmax(0,3fr)_minmax(0,2fr)]">
          <div className="flex min-w-0 flex-col gap-6">
            {REFERENCE_KINDS.slice(0, 2).map((kind) => (
              <CharacterMediaSection key={kind} source={source} kinds={[kind]} />
            ))}
          </div>
          <div className="flex min-w-0 flex-col gap-6">
            {REFERENCE_KINDS.slice(2).map((kind) => (
              <CharacterMediaSection key={kind} source={source} kinds={[kind]} />
            ))}
          </div>
        </TabsContent>
      </Tabs>
    </div>
  )
}
